    LANGUAGE_WRAPPER = "In a repeated coin-toss tournament with {num_players} players labeled 1 through {num_players} sitting in a fixed cyclic order, the games proceed as follows:\n- In each game, starting from the current starter, players take turns (wrapping around cyclically) tossing their own independent biased coins. Player i has head probability p_i.\n- The game ends immediately when someone tosses a head; that player is the winner.\n- The next game's starter is the unique player who would have been next to toss if play had continued—namely, the successor of the winner in that round's turn order.\nInitially, player {starter} is the starter.\nLet m/n (in lowest terms) denote the probability that player {target} wins the {game_index}-th game under these rules. What are the last {last_digits} digits of m+n?\nData: k = {num_players}, and (p_1, p_2, ..., p_k) = {prob_list_str}."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from fractions import Fraction
tries = 0
while True:
    tries += 1
    k = rng.randint(3, 5)
    nums = []
    dens = []
    for _ in range(k):
        d = rng.randint(6, 20)
        n = rng.randint(1, d - 1)
        nums.append(n)
        dens.append(d)
    # ensure not all probabilities identical
    if len(set((nums[i], dens[i]) for i in range(k))) == 1:
        continue
    starter = rng.randint(1, k)
    target = rng.randint(1, k)
    game_index = rng.randint(4, 10)
    last_digits = 3
    p_list = [Fraction(nums[i], dens[i]) for i in range(k)]
    # domain checks
    if any(p <= 0 or p >= 1 for p in p_list):
        continue
    f_list = [Fraction(1, 1) - p for p in p_list]
    Q = Fraction(1, 1)
    for fi in f_list:
        Q *= fi
    if Q == 1:
        continue
    def R(s, i):
        # s, i in 1..k; probability i wins before any prior head in the first pass
        prod = Fraction(1, 1)
        j = s
        while j != i:
            prod *= (Fraction(1, 1) - p_list[j - 1])
            j += 1
            if j > k:
                j = 1
        return prod * p_list[i - 1]
    # build transition matrix T: from starter s to next starter s'
    T = [[Fraction(0, 1) for _ in range(k)] for __ in range(k)]
    for s in range(1, k + 1):
        for sp in range(1, k + 1):
            prev_sp = sp - 1 if sp > 1 else k
            T[s - 1][sp - 1] = R(s, prev_sp) / (Fraction(1, 1) - Q)
    # evolve starter distribution for N-1 transitions
    d = [Fraction(0, 1)] * k
    d[starter - 1] = Fraction(1, 1)
    for _ in range(game_index - 1):
        d_new = [Fraction(0, 1)] * k
        for j in range(k):
            ssum = Fraction(0, 1)
            for i in range(k):
                ssum += d[i] * T[i][j]
            d_new[j] = ssum
        d = d_new
    Pwin_given_s = [R(s, target) / (Fraction(1, 1) - Q) for s in range(1, k + 1)]
    prob = sum(d[s - 1] * Pwin_given_s[s - 1] for s in range(1, k + 1))
    if prob <= 0 or prob >= 1:
        continue
    m = prob.numerator
    n = prob.denominator
    tot = m + n
    # ensure nontrivial final digits
    if tot < 100 and tries < 100:
        continue
    prob_list_str = ", ".join(f"{nums[i]}/{dens[i]}" for i in range(k))
    return {
        'num_players': k,
        'prob_list_str': prob_list_str,
        'starter': starter,
        'target': target,
        'game_index': game_index,
        'last_digits': last_digits,
        'prob_nums': nums,
        'prob_dens': dens
    }

